        margin: 1.5rem 0 0;
        color: var(--color-muted);
        font-size: clamp(1rem, 2vw, 1.2rem);
      }

      .hero-card {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-height: 100%;
        border-radius: var(--radius-xl);
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .cat-portrait {
        display: grid;
        min-height: 13rem;
        place-items: center;
        border-radius: 1.4rem;
        background:
          linear-gradient(135deg, #efe7ff, #fff2de);
        color: var(--color-accent-strong);
        font-size: clamp(4rem, 18vw, 8rem);
      }

      .hero-card h2 {
        margin: 1.25rem 0 0.35rem;
        font-size: 1.35rem;
        line-height: 1.2;
      }

      .hero-card p {
        margin: 0;
        color: var(--color-muted);
      }

      .faq-panel {
        margin: 1rem 0 3rem;
        border-radius: var(--radius-xl);
        padding: clamp(1rem, 4vw, 1.5rem);
      }

      .faq-heading {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        padding: 0.5rem 0.5rem 1.25rem;
      }

      .faq-heading h2 {
        margin: 0;
        font-size: clamp(1.8rem, 4vw, 2.7rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .faq-heading p {
        max-width: 34rem;
        margin: 0;
        color: var(--color-muted);
      }

      .faq-list {
        display: grid;
        gap: 0.85rem;
      }

      .example {
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        background: var(--color-card);
        overflow: clip;
      }

      .faq-question {
        display: grid;
        width: 100%;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: 1rem;
        border: 0;
        background: transparent;
        color: var(--color-text);
        cursor: pointer;
        padding: 1.1rem 1.2rem;
        text-align: left;
      }

      .faq-question:hover {
        background: #f8f5ff;
      }

      .question-text {
        font-size: 1.08rem;
        font-weight: 800;
        overflow-wrap: anywhere;
      }

      .chevron {
        display: grid;
        width: 2rem;
        height: 2rem;
        place-items: center;
        border: 1px solid #cfc4f3;
        border-radius: 999px;
        color: var(--color-accent-strong);
        font-size: 1.3rem;
        font-weight: 900;
        transition: transform 160ms ease;
