      .faq-question[aria-expanded="true"] .chevron {
        transform: rotate(45deg);
      }

      .details {
        border-top: 1px solid var(--color-border);
        color: var(--color-muted);
        padding: 0 1.2rem 1.2rem;
      }

      .details[hidden] {
        display: none;
      }

      .details p {
        max-width: 75ch;
        margin: 1rem 0 0;
      }

      .site-footer {
        color: var(--color-muted);
        padding-block: 0 2rem;
        text-align: center;
