    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals a day, while kittens usually need smaller meals more often. Follow your veterinarian's advice, adjust for age and activity, and keep fresh water available at all times."
        },
        {
          question: "Why does my cat knead blankets or my lap?",
          answer:
            "Kneading is a common comfort behavior that often begins in kittenhood. Many cats knead when they feel relaxed, affectionate, or ready to settle in for a nap."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Puzzle feeders, scratching posts, window perches, climbing spaces, and daily play sessions help indoor cats exercise, explore, and reduce boredom."
        },
        {
          question: "How can I make litter box habits easier?",
          answer:
            "Provide one litter box per cat plus one extra, place boxes in quiet accessible spots, scoop daily, and avoid sudden litter changes. If habits change suddenly, contact a veterinarian to rule out health issues."
        },
        {
          question: "What signs mean my cat may need a vet?",
          answer:
            "Changes in eating, drinking, litter box use, breathing, grooming, energy, or behavior can signal a problem. Prompt veterinary care is especially important if your cat stops eating, seems painful, or has trouble urinating."
        }
      ];

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            "\"": "&quot;",
            "'": "&#039;"
          };
          return entities[character];
        });

      function Header() {
        return `
          <header class="site-header">
            <a class="brand" href="#main" aria-label="Cat Care FAQ home">
              <span class="brand-mark" aria-hidden="true">🐾</span>
              <span>Cat Care FAQ</span>
            </a>
            <nav class="top-nav" aria-label="Page navigation">
              <ul>
                <li><a href="#questions">Questions</a></li>
                <li><a href="#tips">Care tips</a></li>
              </ul>
            </nav>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div class="hero-copy">
              <p class="eyebrow">Modern cat care, simplified</p>
              <h1 id="page-title">Cat questions answered</h1>
              <p>
                A calm, practical FAQ for new and experienced cat people.
                Expand each question to learn quick basics about feeding,
                behavior, enrichment, litter boxes, and health cues.
              </p>
            </div>
            <aside class="hero-card" id="tips" aria-labelledby="tips-title">
              <div class="cat-portrait" aria-hidden="true">🐈</div>
              <div>
                <h2 id="tips-title">Tiny habit, big payoff</h2>
                <p>
                  Ten minutes of interactive play each day can support your
                  cat's body, confidence, and bond with you.
                </p>
              </div>
            </aside>
          </section>
        `;
      }

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-question-${index + 1}`;
        const detailsId = `faq-answer-${index + 1}`;

        return `
          <div class="example">
            <h3>
              <button
                class="faq-question"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${detailsId}"
              >
                <span class="question-text">${escapeHtml(question)}</span>
                <span class="chevron" aria-hidden="true">+</span>
              </button>
            </h3>
            <div
              class="details"
              id="${detailsId}"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${escapeHtml(answer)}</p>
            </div>
          </div>
        `;
      }

      function FAQList() {
        return `
          <section class="faq-panel" id="questions" aria-labelledby="faq-title">
            <div class="faq-heading">
              <h2 id="faq-title">Frequently asked questions</h2>
              <p>
                Questions are collapsed by default. Use Tab to reach a question,
                then press Enter or Space to expand or collapse the answer.
              </p>
            </div>
            <div class="faq-list">
              ${faqs.map(FAQItem).join("")}
            </div>
          </section>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="main">
            ${Hero()}
            ${FAQList()}
          </main>
          <footer class="site-footer">
            <p>Built for curious cat companions.</p>
          </footer>
        `;
      }

      function attachDisclosureBehavior() {
        document.querySelectorAll(".faq-question").forEach((button) => {
          button.addEventListener("click", () => {
            const details = document.getElementById(
              button.getAttribute("aria-controls")
            );
            const isExpanded = button.getAttribute("aria-expanded") === "true";

            button.setAttribute("aria-expanded", String(!isExpanded));
            details.hidden = isExpanded;
          });
        });
      }

      document.getElementById("root").innerHTML = App();
      attachDisclosureBehavior();
    </script>
  </body>
</html>
